    // Each `e[k]` finite and non-negative, a comparison that is false for NaN.
    let valid = (e[0] >= 0.0)
        & (e[0] <= f64::MAX)
        & (e[1] >= 0.0)
        & (e[1] <= f64::MAX)
        & (e[2] >= 0.0)
        & (e[2] <= f64::MAX);
    let decided = valid
        & (AXES_D_MIN <= dx)
        & (dx <= AXES_D_MAX)
        & (AXES_D_MIN <= dy)
        & (dy <= AXES_D_MAX)
        & (AXES_D_MIN <= dz)
        & (dz <= AXES_D_MAX)
        & (det.abs() > bound);
    let sign = if det > 0.0 {
        Sign::Positive
    } else {
        Sign::Negative
    };
