    let l6 = expansion::from_two_product(v0, v3, &mut e6);
    let mut e7 = [0.0; 2];
    let l7 = expansion::from_two_product(v1, v4, &mut e7);
    let mut e8 = [0.0; 4];
    let l8 = expansion::sum(&e6[..l6], &e7[..l7], &mut e8);
    let mut e9 = [0.0; 2];
    let l9 = expansion::from_two_product(v2, v5, &mut e9);
    let mut e10 = [0.0; 6];
    let l10 = expansion::sum(&e8[..l8], &e9[..l9], &mut e10);
    Some(expansion::sign(&e10[..l10]))
