/// other than [`Weight::One`], or some coordinate has more than
/// [`MAX_COORD_COMPONENTS`] components or a nonzero component of magnitude
/// outside [`SPANS_TRANSLATED_RANGE`] or not finite.
///
/// Requirement: every coordinate is a valid expansion of `scratch`: nonzero
/// components of strictly increasing magnitude that do not overlap, as
/// [`Point::exact`](implicit_predicates_core::Point::exact) writes them. This
/// is not checked, and the result is unspecified otherwise.
///
/// The arena is left as it was, on success and on error.
///
/// # Errors
///
/// [`ScratchExhausted`] if `scratch` runs out of room.
#[cold]
#[inline(never)]
pub fn expansions_translated_in(
    scratch: &mut Scratch<'_>,
    p: [&ExactCoords; 3],
) -> Result<Option<Sign>, ScratchExhausted> {
    fn evaluate(scratch: &mut Scratch<'_>, c: [[Span; 3]; 3]) -> Result<Sign, ScratchExhausted> {
        let e0 = scratch.diff(c[0][0], c[1][0])?;
        let e1 = scratch.diff(c[0][1], c[1][1])?;
        let e2 = scratch.diff(c[0][2], c[1][2])?;
        let e3 = scratch.diff(c[2][0], c[1][0])?;
        let e4 = scratch.diff(c[2][1], c[1][1])?;
        let e5 = scratch.diff(c[2][2], c[1][2])?;
        let e6 = scratch.product(e0, e3)?;
        let e7 = scratch.product(e1, e4)?;
        let e8 = scratch.sum(e6, e7)?;
        let e9 = scratch.product(e2, e5)?;
        let e10 = scratch.sum(e8, e9)?;
        Ok(scratch.sign(e10))
    }
    // Every coordinate read must be short enough and within the range; the
    // arena is reset to its mark whatever the evaluation returns.
    if !p.iter().all(|q| q.w == Weight::One) {
        return Ok(None);
    }
    let c = p.map(|q| [q.x, q.y, q.z]);
    let coordinates = [
        c[0][0], c[0][1], c[0][2], c[1][0], c[1][1], c[1][2], c[2][0], c[2][1], c[2][2],
    ];
    if !coordinates
        .into_iter()
        .all(|s| span_in_range(scratch.get(s), SPANS_TRANSLATED_RANGE))
    {
        return Ok(None);
    }
    let mark = scratch.mark();
    let sign = evaluate(scratch, c);
    scratch.reset(mark);
    sign.map(Some)
}

/// The exact sign of the predicate for points given by their coordinates as big
/// integers: its main form evaluated with the big-integer operations of
/// `scratch`, which are exact whatever the size of the values, so this stage
/// always decides.
///
/// For explicit points, [`BIG_INTEGERS_EXPLICIT_ARENA`] slots of `scratch`, the
/// coordinates included, suffice.
///
/// The arena is left as it was, on success and on error.
///
/// # Errors
///
/// [`ScratchExhausted`] if `scratch` runs out of room.
#[cold]
#[inline(never)]
pub fn big_integers_in(
    scratch: &mut Scratch<'_>,
    p: [&BigCoords; 3],
) -> Result<Sign, ScratchExhausted> {
    fn evaluate(scratch: &mut Scratch<'_>, c: [[Big; 3]; 3]) -> Result<Sign, ScratchExhausted> {
        let e0 = scratch.big_sub(c[0][0], c[1][0])?;
        let e1 = scratch.big_sub(c[0][1], c[1][1])?;
        let e2 = scratch.big_sub(c[0][2], c[1][2])?;
        let e3 = scratch.big_sub(c[2][0], c[1][0])?;
        let e4 = scratch.big_sub(c[2][1], c[1][1])?;
        let e5 = scratch.big_sub(c[2][2], c[1][2])?;
        let e6 = scratch.big_mul(e0, e3)?;
        let e7 = scratch.big_mul(e1, e4)?;
        let e8 = scratch.big_add(e6, e7)?;
        let e9 = scratch.big_mul(e2, e5)?;
        let e10 = scratch.big_add(e8, e9)?;
        Ok(e10.sign())
    }
    // The arena is reset to its mark whatever the evaluation returns.
    let c = p.map(|q| [q.x, q.y, q.z]);
    let mark = scratch.mark();
    let sign = evaluate(scratch, c);
    scratch.reset(mark);
    sign
}

/// The sign of the predicate for explicit points, from the first stage that
/// decides.
///
/// Runs [`filter`] with `e = 0.0`, then [`filter_axes`] with `e = [0.0; 3]`,
/// then [`exact_differences`], then [`expansions_translated`]. `None` means
/// that no stage can decide.
#[inline]
pub fn staged(p: [&[f64; 3]; 3]) -> Option<Sign> {
    filter(p, 0.0)
        .or_else(|| filter_axes(p, [0.0; 3]))
        .or_else(|| exact_differences(p))
        .or_else(|| expansions_translated(p))
}

/// [`filter`] on the approximations of points of any type, with the uncertainty
/// of their errors: `0.0` when every point is explicit, and otherwise
/// `uncertainty_max` of their errors, from `implicit_predicates_core::filter`.
///
/// In release builds the errors are not read when every point is explicit. When
/// that is known from the types, as with `[f64; 3]`, whose `is_explicit` is the
/// constant `true`, this is then `filter` with `e = 0.0`. Debug builds first
/// check the errors of each point: none is NaN or negative, and an explicit
/// point has none.
#[inline]
pub fn filter_points<P0: Point, P1: Point, P2: Point>(p0: &P0, p1: &P1, p2: &P2) -> Option<Sign> {
    debug_check_err(0, p0);
    debug_check_err(1, p1);
    debug_check_err(2, p2);
    let p = [p0.approx(), p1.approx(), p2.approx()];
    let e = if p0.is_explicit() & p1.is_explicit() & p2.is_explicit() {
        0.0
    } else {
        implicit_predicates_core::filter::uncertainty_max([p0.err(), p1.err(), p2.err()])
    };
    filter(p, e)
}

/// [`filter_axes`] on the approximations of points of any type, with the
