/// that is known from the types, as with `[f64; 3]`, whose `is_explicit` is the
/// constant `true`, this is then `filter_axes` with `e = [0.0; 3]`. Debug
/// builds first check the errors of each point: none is NaN or negative, and an
/// explicit point has none.
#[inline]
pub fn filter_axes_points<P0: Point, P1: Point, P2: Point>(
    p0: &P0,
    p1: &P1,
    p2: &P2,
) -> Option<Sign> {
    debug_check_err(0, p0);
    debug_check_err(1, p1);
    debug_check_err(2, p2);
    let p = [p0.approx(), p1.approx(), p2.approx()];
    let e = if p0.is_explicit() & p1.is_explicit() & p2.is_explicit() {
        [0.0; 3]
    } else {
        implicit_predicates_core::filter::uncertainty([p0.err(), p1.err(), p2.err()])
    };
    filter_axes(p, e)
}

