/// to `scratch`, which always decides. The stage over spans is skipped when a
/// point cannot give its exact coordinates as expansions, as when its inputs
/// are outside the range of its exact arithmetic ([`ExactError::OutOfRange`]).
/// Each attempt starts from the mark of `scratch` on entry, to which it is
/// reset whatever they return.
///
/// # Errors
///
/// [`ScratchExhausted`] if `scratch` runs out of room.
///
/// # Panics
///
/// If the exact coordinates of a point have a weight other than
/// [`Weight::One`], which the predicates do not support, or a point cannot give
/// its exact coordinates as big integers, which by the contract of
/// [`Point::exact_big`] happens only when an input is not finite or the
/// coordinates have a weight other than one.
#[cold]
#[inline(never)]
pub fn exact_stages_in<P0: Point, P1: Point, P2: Point>(
    scratch: &mut Scratch<'_>,
    p0: &P0,
    p1: &P1,
    p2: &P2,
) -> Result<Sign, ScratchExhausted> {
    fn spans<P0: Point, P1: Point, P2: Point>(
        scratch: &mut Scratch<'_>,
        p0: &P0,
        p1: &P1,
        p2: &P2,
    ) -> Result<Option<Sign>, ScratchExhausted> {
        let q0 = exact(scratch, 0, p0)?;
        let q1 = exact(scratch, 1, p1)?;
        let q2 = exact(scratch, 2, p2)?;
        let (Some(q0), Some(q1), Some(q2)) = (q0, q1, q2) else {
            return Ok(None);
        };
        let q = [&q0, &q1, &q2];
        expansions_translated_in(scratch, q)
    }
    fn big<P0: Point, P1: Point, P2: Point>(
        scratch: &mut Scratch<'_>,
        p0: &P0,
        p1: &P1,
        p2: &P2,
    ) -> Result<Sign, ScratchExhausted> {
        let q0 = exact_big(scratch, 0, p0)?;
        let q1 = exact_big(scratch, 1, p1)?;
        let q2 = exact_big(scratch, 2, p2)?;
        big_integers_in(scratch, [&q0, &q1, &q2])
    }
    if let Some(sign) = filter_axes_points(p0, p1, p2) {
        return Ok(sign);
    }
    let mark = scratch.mark();
    let decided = spans(scratch, p0, p1, p2);
    scratch.reset(mark);
    if let Some(sign) = decided? {
        return Ok(sign);
    }
    let result = big(scratch, p0, p1, p2);
    scratch.reset(mark);
    result
}

/// The sign of the predicate for points of any type, from the first stage that
/// decides.
///
/// Runs [`filter_points`]; then, when every point is explicit,
/// [`exact_stages_explicit_in`] on their coordinates; otherwise
/// [`exact_stages_in`], on their exact coordinates written to `scratch`.
/// `scratch` is not used when the filter decides, and is left as it was. Every
/// call decides: the last stage, [`big_integers_in`], always does.
///
/// # Errors
///
/// [`ScratchExhausted`] if `scratch` runs out of room.
///
/// # Panics
///
/// If an input of a point is not finite, or the exact coordinates of a point
/// have a weight other than one, as [`exact_stages_in`] says. In debug builds,
/// also if a point breaks an obligation of the contract of [`Point`] that the
/// chain checks without room in the arena: an error bound that is NaN or
/// negative, an error that is not zero on a point that says it is explicit, or
/// exact coordinates that are not valid expansions or big integers in their
/// unique representation, below the top of `scratch`.
#[inline]
pub fn staged_in<P0: Point, P1: Point, P2: Point>(
    scratch: &mut Scratch<'_>,
    p0: &P0,
    p1: &P1,
    p2: &P2,
) -> Result<Sign, ScratchExhausted> {
    if let Some(sign) = filter_points(p0, p1, p2) {
        return Ok(sign);
    }
    if p0.is_explicit() & p1.is_explicit() & p2.is_explicit() {
        return exact_stages_explicit_in(scratch, [p0.approx(), p1.approx(), p2.approx()]);
    }
    exact_stages_in(scratch, p0, p1, p2)
}

/// The exact coordinates of the point `p`, written to `scratch`, or `None` if
/// it cannot give them for any reason other than the room of the arena, such as
/// inputs outside the range of its exact arithmetic. `position` is the position
/// of `p` among the arguments of the predicate.
///
/// # Panics
///
/// If the coordinates have a weight other than [`Weight::One`], which the
/// predicates do not support; in debug builds, if they break the contract of
/// [`Point`] as [`debug_check_expansions`] says.
fn exact(
    scratch: &mut Scratch<'_>,
    position: usize,
    p: &impl Point,
) -> Result<Option<ExactCoords>, ScratchExhausted> {
    match p.exact(scratch) {
        Ok(c) if c.w != Weight::One => no_exact_coordinates(
            "implicit-predicates: a point has a weight other than one, which the predicates do not support",
        ),
        Ok(c) => {
            debug_check_expansions(scratch, position, &c);
            Ok(Some(c))
        }
        Err(ExactError::Exhausted(e)) => Err(e),
        Err(_) => Ok(None),
    }
}

/// Checks, in debug builds, that every span of `c`, the exact coordinates of
/// the argument `position` of the predicate, holds a valid expansion of
/// `scratch`, below its top, as the contract of [`Point::exact`] requires. It
/// needs no room in the arena.
///
/// # Panics
///
/// In debug builds, if a span does not.
#[inline(always)]
fn debug_check_expansions(scratch: &Scratch<'_>, position: usize, c: &ExactCoords) {
    for (axis, span) in [c.x, c.y, c.z].into_iter().enumerate() {
        debug_assert!(
            implicit_predicates_core::contract::expansion_is_valid(scratch, span),
            "breaks the contract of `Point`: argument {position}: the exact coordinate on axis {axis} is not a valid expansion",
        );
    }
}

/// The exact coordinates of the point `p` as big integers, written to
/// `scratch`. `position` is the position of `p` among the arguments of the
/// predicate.
///
/// # Panics
///
/// If `p` cannot give them for any reason other than the room of the arena: by
/// the contract of [`Point::exact_big`], only when an input is not finite or
/// the coordinates have a weight other than one; in debug builds, if they break
/// the contract of [`Point`] as [`debug_check_big`] says.
fn exact_big(
    scratch: &mut Scratch<'_>,
    position: usize,
    p: &impl Point,
) -> Result<BigCoords, ScratchExhausted> {
    match p.exact_big(scratch) {
        Ok(c) => {
            debug_check_big(scratch, position, &c);
            Ok(c)
        }
        Err(ExactError::Exhausted(e)) => Err(e),
        Err(ExactError::Weighted) => no_exact_coordinates(
            "implicit-predicates: a point has a weight other than one, which the predicates do not support",
        ),
        Err(_) => no_exact_coordinates(
            "implicit-predicates: a point has no exact coordinates: an input is not finite",
        ),
    }
}

/// Ends a call whose points cannot give the exact coordinates the predicate
/// needs, with a panic of message `reason`: the chain never returns a sign it
/// has not computed exactly.
#[cold]
#[inline(never)]
fn no_exact_coordinates(reason: &str) -> ! {
    panic!("{reason}")
}

/// Checks, in debug builds, that `p`, the argument `position` of the predicate,
/// keeps the obligations of the contract of [`Point`] on its errors: no
/// [`Point::err`] is NaN or negative, and a point whose [`Point::is_explicit`]
/// is `true` has no error. It needs no arena.
///
/// # Panics
///
/// In debug builds, if `p` breaks one of them.
#[inline(always)]
fn debug_check_err(position: usize, p: &impl Point) {
    debug_assert!(
        implicit_predicates_core::contract::err_is_valid(p.err()),
        "breaks the contract of `Point`: argument {position}: an error bound is NaN or negative: {:?}",
        p.err(),
    );
    debug_assert!(
        !p.is_explicit() || *p.err() == [0.0; 3],
        "breaks the contract of `Point`: argument {position}: the point says it is explicit, but its error bound is not zero: {:?}",
        p.err(),
    );
}

/// Checks, in debug builds, that every coordinate of `c`, the exact coordinates
/// as big integers of the argument `position` of the predicate, is in the
/// unique representation of a [`Big`], with its words below the top of
/// `scratch`, as the contract of [`Point::exact_big`] requires. It needs no
/// room in the arena.
///
/// # Panics
///
/// In debug builds, if a coordinate is not.
#[inline(always)]
fn debug_check_big(scratch: &Scratch<'_>, position: usize, c: &BigCoords) {
    for (axis, b) in [c.x, c.y, c.z].into_iter().enumerate() {
        debug_assert!(
            implicit_predicates_core::contract::big_is_canonical(scratch, b),
            "breaks the contract of `Point`: argument {position}: the exact coordinate on axis {axis} as a big integer is not in its unique representation",
        );
    }
}

/// The larger of `a` and `b`, or `b` if they are unordered.
#[inline]
fn max(a: f64, b: f64) -> f64 {
    if a > b { a } else { b }
}

/// `start` times `d[k]` repeated `g[k]` times, on each axis `k` in turn: a
/// chain of products from left to right, each rounded, that starts with
/// `start`.
#[inline(always)]
fn product_chain(start: f64, g: [u32; 3], d: [f64; 3]) -> f64 {
    let mut x = start;
    for (&n, &dk) in g.iter().zip(&d) {
        for _ in 0..n {
            x *= dk;
        }
    }
    x
}

/// Whether `x` is zero or has a magnitude in `min..=max`; false for NaN and
/// infinities.
fn in_range(x: f64, (min, max): (f64, f64)) -> bool {
    x == 0.0 || (min..=max).contains(&x.abs())
}

/// Whether the expansion `e` has at most [`MAX_COORD_COMPONENTS`] components,
/// each of a magnitude in `min..=max`. A zero component is not: zero is the
/// empty expansion, and an expansion with a zero component is not valid.
fn span_in_range(e: &[f64], (min, max): (f64, f64)) -> bool {
    e.len() <= MAX_COORD_COMPONENTS && e.iter().all(|&x| (min..=max).contains(&x.abs()))
}

/// Writes the expansion of `x * y` to `out` and returns its length: the sum of
/// the scalings of `y` by each component of `x`, each scaling written to
/// `scaled`, the partial sums alternating between `spare` and `out`.
fn product(x: &[f64], y: &[f64], scaled: &mut [f64], spare: &mut [f64], out: &mut [f64]) -> usize {
    let Some((&first, rest)) = x.split_first() else {
        return 0;
    };
    // Start so that the last partial sum is written to `out`.
    let (mut partial, mut next) = if rest.len() % 2 == 0 {
        (out, spare)
    } else {
        (spare, out)
    };
    let mut length = expansion::scale(y, first, partial);
    for &component in rest {
        let scaled_length = expansion::scale(y, component, scaled);
        length = expansion::sum(&partial[..length], &scaled[..scaled_length], next);
        core::mem::swap(&mut partial, &mut next);
    }
    length
}
